UPDATE A SET A.EQU_NAME = U.EQU_NAME, A.SIZE = U.SIZE, A.FORM = U.FORM, A.MAKE_BY = U.MAKE_BY, A.DIMENSION = U.DIMENSION, A.INSTALL_DATE = U.INSTALL_DATE, A.INSTALL_PLACE = U.INSTALL_PLACE, A.DISUSE_GBN = U.DISUSE_GBN FROM dbo.TEC_EQUIPMENT A JOIN (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO, #{row.EQU_NAME} AS EQU_NAME, #{row.SIZE} AS SIZE, #{row.FORM} AS FORM, #{row.MAKE_BY} AS MAKE_BY, #{row.DIMENSION} AS DIMENSION, #{row.INSTALL_DATE} AS INSTALL_DATE, #{row.INSTALL_PLACE} AS INSTALL_PLACE, #{row.DISUSE_GBN} AS DISUSE_GBN
) U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.EQU_GBN = U.EQU_GBN AND A.EQU_NO = U.EQU_NO

mapper.delete:
DELETE FROM dbo.TEC_EQUIPMENT WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGIN_OFFICE_CODE} AS OFFICE_CODE, #{row.EQU_GBN} AS EQU_GBN, #{row.EQU_NO} AS EQU_NO
) AS temp WHERE temp.OFFICE_CODE = TEC_EQUIPMENT.OFFICE_CODE AND temp.EQU_GBN = TEC_EQUIPMENT.EQU_GBN AND temp.EQU_NO = TEC_EQUIPMENT.EQU_NO )

